create or replace function public.attendance_check_in(p_lat numeric,p_lng numeric,p_selfie_path text,p_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid(); v_row public.attendance%rowtype; v_date date:=(now() at time zone 'Asia/Kolkata')::date; begin if v_uid is null then raise exception 'Authentication required'; end if; if p_lat is null or p_lng is null or p_lat < -90 or p_lat > 90 or p_lng < -180 or p_lng > 180 then raise exception 'Valid GPS coordinates are required'; end if; if p_selfie_path is null or split_part(p_selfie_path,'/',1)<>v_uid::text then raise exception 'A selfie uploaded to your private folder is required'; end if; insert into public.attendance(user_id,attendance_date,check_in,check_in_lat,check_in_lng,check_in_selfie_path,check_in_note,status) values(v_uid,v_date,now(),p_lat,p_lng,p_selfie_path,nullif(p_note,''),'present') on conflict(user_id,attendance_date) do nothing returning * into v_row; if not found then raise exception 'You have already checked in today'; end if; return to_jsonb(v_row); end; $$;
create or replace function public.attendance_check_out(p_lat numeric,p_lng numeric,p_selfie_path text,p_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid(); v_row public.attendance%rowtype; v_date date:=(now() at time zone 'Asia/Kolkata')::date; begin if v_uid is null then raise exception 'Authentication required'; end if; if p_lat is null or p_lng is null or p_lat < -90 or p_lat > 90 or p_lng < -180 or p_lng > 180 then raise exception 'Valid GPS coordinates are required'; end if; if p_selfie_path is null or split_part(p_selfie_path,'/',1)<>v_uid::text then raise exception 'A selfie uploaded to your private folder is required'; end if; update public.attendance set check_out=now(),check_out_lat=p_lat,check_out_lng=p_lng,check_out_selfie_path=p_selfie_path,check_out_note=nullif(p_note,''),updated_at=now() where user_id=v_uid and attendance_date=v_date and check_in is not null and check_out is null returning * into v_row; if not found then raise exception 'No open check-in found for today'; end if; return to_jsonb(v_row); end; $$;
revoke all on function public.attendance_check_in(numeric,numeric,text,text) from public,anon; revoke all on function public.attendance_check_out(numeric,numeric,text,text) from public,anon; grant execute on function public.attendance_check_in(numeric,numeric,text,text) to authenticated; grant execute on function public.attendance_check_out(numeric,numeric,text,text) to authenticated;